import {printTypography,printRowHeight,measurePrintText} from './print-typography.js';
import {makePrintDocuments,buildPrintPages,estPrintSettings,printPageSvg,printPagesHtml,printVectorCss} from './est-print.js';
import {collectEvidence} from './project-data.js';
import {pdfFileName} from './project-labels.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const allPreviewSettings=(settings,bundle)=>({...settings,sections:bundle.documents.filter(d=>d.rows.length).map(d=>d.key)});
export function setupEstPrintPreview(api){
 const css=document.createElement('link');css.rel='stylesheet';css.href='est-print-preview.css';document.head.append(css);
 const dialog=document.createElement('dialog');dialog.id='estPrintPreview';dialog.setAttribute('aria-label','인쇄 미리보기');
 dialog.innerHTML=`<div class="ep-title"><strong>인쇄 미리보기</strong><span id="epProject"></span><button id="epClose" aria-label="미리보기 닫기">×</button></div><div class="ep-toolbar"><button id="epPrint">인쇄</button><button id="epPdf">PDF 저장</button><button id="epPrinter">프린터 설정</button><span class="ep-divider"></span><button id="epChoose">인쇄 항목</button><button id="epOptions">인쇄 옵션</button><button id="epFirst" aria-label="첫 페이지">|◀</button><button id="epPrev" aria-label="이전 페이지">◀</button><span id="epPage" aria-live="polite"></span><button id="epNext" aria-label="다음 페이지">▶</button><button id="epLast" aria-label="끝 페이지">▶|</button><label>시작번호 <input id="epStart" type="number" min="1" max="99999" value="1"></label><select id="epZoom" aria-label="미리보기 배율"><option value="fit">한 쪽 맞춤</option><option value="width">폭 맞춤</option><option value=".75">75%</option><option value="1">100%</option><option value="1.25">125%</option><option value="1.5">150%</option></select><span class="ep-divider"></span><button id="epSaveStyle">기본양식 저장</button><button id="epLoadStyle">기본양식 열기</button><button id="epOther">기타 문서 출력</button></div><div class="ep-body"><aside><div class="ep-list-title">인쇄항목 <button id="epSelectAll">전체</button></div><div id="epDocuments"></div><p class="ep-side-note">전체 문서를 미리 봅니다. 체크는 인쇄할 문서를 지정합니다.</p></aside><main id="epStage"><div id="epPaper"></div></main><section id="epSettings" hidden><h3 id="epOptionTitle">인쇄 옵션</h3><label>용지 방향<select id="epOrientation"><option value="portrait">A4 세로</option><option value="landscape">A4 가로</option></select></label><label>글자 크기(pt)<input id="epFont" type="number" min="6" max="16" step=".5"></label><label hidden>글자 가로 폭(%)<input id="epFontWidth" type="number" min="30" max="120" step="1"></label><label hidden>자간(pt)<input id="epSpacing" type="number" min="-1" max="3" step=".1"></label><label>행 높이(mm)<input id="epRow" type="number" min="3" max="15" step=".01"></label><label>왼쪽 여백(mm)<input id="epLeft" type="number" min="2" max="40" step=".5"></label><label>오른쪽 여백(mm)<input id="epRight" type="number" min="2" max="40" step=".5"></label><label class="ep-check"><input id="epItemBreak" type="checkbox">단가 항목마다 새 페이지</label><label class="ep-check"><input id="epGroupBreak" type="checkbox">공종마다 새 페이지</label><label>새 페이지를 시작할 행 번호<input id="epBreaks" placeholder="예: 12, 24"></label><p>현재 선택한 문서에 적용합니다. 미리보기·인쇄·PDF·엑셀에 같은 양식을 적용합니다.</p><button id="epOptionApply">옵션 적용</button><button id="epOptionReset">기본값 복원</button></section></div><div class="ep-status"><span id="epStatus" role="status"></span><span>굴림체 · A4 · 흑백 양식</span></div>`;
 document.body.append(dialog);
 const chooser=document.createElement('dialog');chooser.id='estPrintChooser';chooser.setAttribute('aria-label','인쇄할 항목 선택');chooser.innerHTML=`<div class="ep-choice-head"><div><h2>인쇄할 항목 선택</h2><p>체크한 문서만 인쇄합니다. 마지막 선택은 다음 실행에도 유지됩니다.</p></div><button id="epChoiceClose" aria-label="인쇄 항목 선택 닫기">×</button></div><div class="ep-choice-tools"><button id="epChoiceAll">전체 선택</button><button id="epChoiceNone">전체 해제</button></div><div id="epChoiceList"></div><p id="epChoiceNote" role="status"></p><div class="ep-choice-footer"><button id="epChoiceCancel">취소</button><button id="epChoiceApply" class="primary">선택 항목 미리보기</button></div>`;document.body.append(chooser);
 const choose=id=>chooser.querySelector('#'+id);
 const $=id=>dialog.querySelector('#'+id);let bundle=null,pages=[],settings={},index=0,selectedKey='summary',source=null,printing=false,allPreview=true,choiceAction='select';
 // The workbook and PDF use these same GulimChe advances. Browser fallback
 // font metrics must not change line breaks or fitted sizes in the preview.
 const measure=measurePrintText;
 function message(s){$('epStatus').textContent=s;}
 function selectionCount(){const count=choose('epChoiceList').querySelectorAll('input:checked').length;choose('epChoiceNote').textContent=count?count+'개 문서 선택 · 목록 순서대로 출력합니다.':'출력할 문서를 하나 이상 선택하세요.';choose('epChoiceApply').disabled=!count;}
 function chooseDocuments(action='select'){choiceAction=action;choose('epChoiceApply').textContent=action==='print'?'선택 항목 인쇄':'선택 항목 적용';choose('epChoiceList').innerHTML=bundle.documents.map(d=>`<label><input type="checkbox" value="${d.key}" ${settings.sections.includes(d.key)&&d.rows.length?'checked':''} ${!d.rows.length?'disabled':''}><span>${esc(d.title)}</span>${!d.rows.length?'<small>자료 없음</small>':''}</label>`).join('');selectionCount();chooser.showModal();}
 const rememberChoice=()=>{selectionCount();const sections=[...choose('epChoiceList').querySelectorAll('input:checked')].map(x=>x.value);settings={...settings,sections};api.outputPreferences?.set('print',settings);list();};
 choose('epChoiceList').onchange=rememberChoice;
 choose('epChoiceAll').onclick=()=>{choose('epChoiceList').querySelectorAll('input:not(:disabled)').forEach(x=>x.checked=true);rememberChoice();};
 choose('epChoiceNone').onclick=()=>{choose('epChoiceList').querySelectorAll('input').forEach(x=>x.checked=false);rememberChoice();};
 choose('epChoiceClose').onclick=choose('epChoiceCancel').onclick=()=>chooser.close();
 choose('epChoiceApply').onclick=async()=>{try{const next=estPrintSettings({...settings,sections:[...choose('epChoiceList').querySelectorAll('input:checked')].map(x=>x.value)});buildPrintPages(bundle,next,measure);settings=next;save();await api.outputPreferences?.settled();chooser.close();if(choiceAction==='print'){await print();return;}pages=buildPrintPages(bundle,allPreview?allPreviewSettings(settings,bundle):settings,measure);index=0;if(!dialog.open)dialog.showModal();show();}catch(e){choose('epChoiceNote').textContent=e.message;}};
 $('epChoose').onclick=()=>chooseDocuments('select');

 const safe=fn=>async()=>{try{await fn();}catch(e){message(e.message);}};
 function save(){api.outputPreferences?.set('print',settings);api.getProject().estPrintSettings=structuredClone(settings);api.commit();}
 function list(){const selected=new Set(settings.sections);$('epDocuments').innerHTML=bundle.documents.map(d=>{const count=pages.filter(p=>p.document===d.key).length;return `<div class="ep-document ${selectedKey===d.key?'selected':''}"><input type="checkbox" data-ep-select="${d.key}" aria-label="${esc(d.title)} 인쇄" ${selected.has(d.key)?'checked':''} ${!d.rows.length?'disabled':''}><button data-ep-document="${d.key}" ${!d.rows.length?'disabled':''}>${esc(d.title)}<small>${d.rows.length?(count?count+'쪽':'선택 안 함'):'자료 없음'}</small></button></div>`;}).join('');}
 function fit(){const p=pages[index];if(!p)return;const stage=$('epStage'),svg=$('epPaper').querySelector('svg');if(!svg)return;const mode=$('epZoom').value,w=p.width*96/72,h=p.height*96/72,z=mode==='fit'?Math.min((stage.clientWidth-48)/w,(stage.clientHeight-40)/h):mode==='width'?(stage.clientWidth-48)/w:Number(mode);$('epPaper').style.width=Math.max(.15,z)*w+'px';$('epPaper').style.height=Math.max(.15,z)*h+'px';}
 function show(){const p=pages[index];if(!p){$('epPaper').innerHTML='';$('epPage').textContent='0 / 0';list();return;}selectedKey=p.document;$('epPaper').innerHTML=printPageSvg(p);$('epPage').textContent=`${index+1} / ${pages.length}`;$('epFirst').disabled=$('epPrev').disabled=index===0;$('epLast').disabled=$('epNext').disabled=index===pages.length-1;list();fit();message(`${p.title} · 출력번호 ${p.number} · ${pages.length}쪽${bundle.warnings.length?' · 산출근거 확인 '+bundle.warnings.length+'건':''}`);if(!$('epSettings').hidden)loadOptions();}
 function rebuild(){settings=estPrintSettings(settings);const prior=selectedKey;pages=buildPrintPages(bundle,allPreview?allPreviewSettings(settings,bundle):settings,measure);index=Math.max(0,pages.findIndex(p=>p.document===prior));show();save();}
 function loadOptions(){const doc=bundle.documents.find(d=>d.key===selectedKey),d=settings.documents[selectedKey]||{},landscape=(d.orientation||doc.orientation)==='landscape';$('epOptionTitle').textContent=doc.title+' 인쇄 옵션';$('epOrientation').value=d.orientation||doc.orientation;$('epFont').value=d.size||printTypography(selectedKey).size;$('epFontWidth').value=d.fontWidth??printTypography(selectedKey).fontWidth;$('epSpacing').value=d.letterSpacing??0;const native=bundle.native?.sheets.find(s=>s.name===doc.title);$('epRow').value=d.rowHeight||Number((native?native.rows[native.header.length]?.height*25.4/72:printRowHeight(doc)).toFixed(2));$('epLeft').value=d.marginLeft??(native?native.print.left*25.4:landscape?24:18.5);$('epRight').value=d.marginRight??(native?native.print.right*25.4:landscape?18:22.5);$('epItemBreak').checked=!!d.itemNewPage;$('epGroupBreak').checked=!!d.groupNewPage;$('epBreaks').value=(d.breakRows||[]).join(',');}
 $('epDocuments').addEventListener('click',e=>{const b=e.target.closest('[data-ep-document]');if(!b)return;const pos=pages.findIndex(p=>p.document===b.dataset.epDocument);if(pos<0){message('왼쪽 체크박스를 선택하면 미리보기에 포함됩니다.');return;}index=pos;show();});
 $('epDocuments').addEventListener('change',e=>{if(!e.target.dataset.epSelect)return;const previous=[...settings.sections];settings.sections=bundle.documents.filter(d=>d.rows.length&&$('epDocuments').querySelector(`[data-ep-select="${d.key}"]`)?.checked).map(d=>d.key);try{rebuild();}catch(err){settings.sections=previous;list();message(err.message);}});
 $('epSelectAll').onclick=safe(()=>{settings.sections=bundle.documents.filter(d=>d.rows.length).map(d=>d.key);rebuild();});
 $('epFirst').onclick=()=>{index=0;show();};$('epLast').onclick=()=>{index=pages.length-1;show();};$('epPrev').onclick=()=>{index=Math.max(0,index-1);show();};$('epNext').onclick=()=>{index=Math.min(pages.length-1,index+1);show();};$('epZoom').onchange=fit;
 $('epStart').onchange=safe(()=>{settings.startPage=Number($('epStart').value);rebuild();});
 $('epOptions').onclick=()=>{$('epSettings').hidden=!$('epSettings').hidden;if(!$('epSettings').hidden)loadOptions();fit();};
 $('epOptionApply').onclick=safe(()=>{const next={...settings,documents:{...settings.documents,[selectedKey]:{orientation:$('epOrientation').value,size:Number($('epFont').value),fontWidth:Number($('epFontWidth').value),letterSpacing:Number($('epSpacing').value),rowHeight:Number($('epRow').value),marginLeft:Number($('epLeft').value),marginRight:Number($('epRight').value),itemNewPage:$('epItemBreak').checked,groupNewPage:$('epGroupBreak').checked,breakRows:$('epBreaks').value}}};const valid=estPrintSettings(next),built=buildPrintPages(bundle,allPreview?allPreviewSettings(valid,bundle):valid,measure);settings=valid;pages=built;index=Math.max(0,pages.findIndex(p=>p.document===selectedKey));show();save();});
 $('epOptionReset').onclick=safe(()=>{delete settings.documents[selectedKey];rebuild();});
 $('epSaveStyle').onclick=safe(async()=>{await api.saveStyle({schema:'est-print-v1',...structuredClone(settings)});message('기본 인쇄양식을 저장했습니다.');});
 $('epLoadStyle').onclick=safe(async()=>{const saved=await api.loadStyle();if(!saved)throw Error('저장한 기본 인쇄양식이 없습니다.');settings=estPrintSettings(saved);$('epStart').value=settings.startPage;rebuild();});
 $('epClose').onclick=()=>dialog.close();$('epOther').onclick=()=>{dialog.close();api.other();};
 async function print(){const selectedPages=buildPrintPages(bundle,settings,measure);save();await api.outputPreferences?.settled();const surface=document.getElementById('printSurface');surface.innerHTML='<style>'+printVectorCss+'</style>'+printPagesHtml(selectedPages);surface.hidden=false;document.body.classList.add('printing-pack');printing=true;dialog.close();window.print();}
 $('epPrint').onclick=$('epPrinter').onclick=()=>chooseDocuments('print');
 $('epPdf').onclick=safe(async()=>{const selectedPages=buildPrintPages(bundle,settings,measure);save();$('epPdf').disabled=true;message('미리보기 양식으로 PDF를 저장하고 있습니다…');try{const r=await fetch('./api/print/pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:source.title,pages:selectedPages})});if(!r.ok){const e=await r.json().catch(()=>({}));throw Error(e.error||'PDF 저장은 공사노트 EXE에서 사용할 수 있습니다. 인쇄에서 PDF 저장을 선택해도 됩니다.');}const saved=await api.download(new Uint8Array(await r.arrayBuffer()),pdfFileName(source.title),'application/pdf');message(saved?.cancelled?'PDF 저장을 취소했습니다.':'미리보기와 같은 양식으로 PDF를 저장했습니다.');}finally{$('epPdf').disabled=false;}});
 window.addEventListener('afterprint',()=>{if(!printing)return;printing=false;document.body.classList.remove('printing-pack');const surface=document.getElementById('printSurface');surface.hidden=true;surface.innerHTML='';if(bundle&&!dialog.open)dialog.showModal();});
 new ResizeObserver(fit).observe($('epStage'));dialog.addEventListener('keydown',e=>{if(e.target.closest('input,select'))return;if(['PageDown','ArrowRight','PageUp','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();index=e.key==='Home'?0:e.key==='End'?pages.length-1:Math.max(0,Math.min(pages.length-1,index+(['PageDown','ArrowRight'].includes(e.key)?1:-1)));show();}if(e.ctrlKey&&e.key.toLowerCase()==='p'){e.preventDefault();chooseDocuments('print');}});
 return {async open(ids=null,{preview=true}={}){allPreview=true;source=structuredClone(api.getProject());if(ids){source.lines=source.lines.filter(l=>ids.includes(l.id));source.title+=' · 선택 범위';}source.evidence=collectEvidence(source,api.getLibraries());await document.fonts.ready;bundle=makePrintDocuments(source,api.getLibraries());settings=estPrintSettings(await api.outputPreferences?.get('print')||source.estPrintSettings||await api.loadStyle()||{});$('epStart').value=settings.startPage;$('epProject').textContent=source.title;pages=buildPrintPages(bundle,allPreviewSettings(settings,bundle),measure);index=0;if(preview){dialog.showModal();show();}else chooseDocuments('print');}};
}
